\label{theo:quadratic-floor}
For any activation, any feature distribution, any data distribution, and any unit target for which~\eqref{eq:main-fixed-point}--\eqref{eq:main-two-term} are defined, every stopping time $t$ satisfies
\begin{equation}\label{eq:quadratic-floor}
\overline{\mathcal L}_{\rm ST}(t)\ge
\nu^2\langle\Psi^{1/2}\beta,(\Psi+\nu I)^{-2}\Psi^{1/2}\beta\rangle
\ge\overline{\mathcal L}_{\rm TE}^{\,2}.
\end{equation}

\label{theo:weaktostrongrelu}
Let $f^\star$ be a unit spherical harmonic of fixed degree $k_0\in\mathcal K$, $k_0\ge1$, and let $m=d^\alpha$ with fixed $\alpha>0$. Then, with
\begin{equation}\label{eq:quadratic-stop}
T=\frac{\log m+\log \overline{\mathcal L}_{\rm TE}^{-1}}{\sigma_{k_0}^2},\qquad
\overline{\mathcal L}_{\rm TE}\asymp d^{-(\alpha-k_0)_+},
\qquad
\overline{\mathcal L}_{\rm ST}(T)\asymp \overline{\mathcal L}_{\rm TE}^2.
\end{equation}

\label{lemma:optimalweigth}
    Given the setting of Section \ref{sec:setup}, for the squared population loss of the teacher
    \begin{equation}
        \mathcal{L}_{\mathrm{TE}} = \mathbb{E}_{x \sim \mathcal{D}}\left[(f_{\mathrm{teacher}}(x)-f^{*}(x))^2\right],
    \end{equation}
    we have that the optimal weight is
    \begin{equation}
        w_{*} = (U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta
    \end{equation}
    where $U_{m}\coloneqq U/\sqrt{m}$, and $U\in \mathbb{R}^{m \times d}$ has the fixed weight vectors $u_{i}\in \mathbb{R}^{d}$ as its rows. With that, we obtain
    \begin{equation}
        \mathcal{L}_{\mathrm{TE}} = \langle U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta - \beta, \Psi[U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta -\beta]\rangle.
    \end{equation}

Just plugging in the definitions, we get 
\begin{equation}\label{eq:teacherpopulationerror}
\begin{split}
    \mathcal{L}_{\mathrm{TE}} &= \mathbb{E}_{x \sim \mathcal{D}}\left[(f_{\mathrm{teacher}}(x)-f^{*}(x))^2\right]\\
    &= \mathbb{E}_{x \sim \mathcal{D}}\left[\left(\frac{1}{\sqrt{m}}w^{T}Ux-\beta^{ T}x\right)^2\right]\\
    &= \mathbb{E}_{x \sim \mathcal{D}}\left[\left(\sum_{l=1}^{d}\left(\frac{1}{\sqrt{m}}\sum_{k=1}^{m}w_{k}U_{kl}x_{l}-\beta_{l}x_{l}\right)\right)^{2}\right]\\
    &=\sum_{l=1}^{d}\psi_{l}\left(\frac{1}{\sqrt{m}}\sum_{k=1}^{m}w_{k}U_{kl}-\beta_{l}\right)^2
\end{split}
\end{equation}
where $w \in \mathbb{R}^{m}$ is the vector of trainable weights.

Thus, the optimal weight $w_{*} \in \mathbb{R}^{m}$ is given by
\begin{equation}
    w_{*} \coloneqq \operatorname*{arg\,min}_{w\in \mathbb{R}^{m}} \left\langle \frac{1}{\sqrt{m}}U^Tw-\beta, \Psi\left(\frac{1}{\sqrt{m}}U^{T}w-\beta\right)\right\rangle.
\end{equation}
and it solves
\begin{equation}\label{eq:optimalweigth}
    \nabla_{w}\left\langle \frac{1}{\sqrt{m}}U^Tw-\beta, \Psi\left(\frac{1}{\sqrt{m}}U^{T}w-\beta\right)\right\rangle = 0.
\end{equation}
Using that
\begin{equation}
\begin{split}
    \nabla_{w}\left\langle \frac{1}{\sqrt{m}}U^Tw-\beta, \Psi\left(\frac{1}{\sqrt{m}}U^{T}w-\beta\right)\right\rangle &= \left(\frac{1}{\sqrt{m}}U^{T}w-\beta\right)^{T}(\Psi+\Psi^{T})\nabla_{w}\left(\frac{1}{\sqrt{m}}U^{T}w-\beta\right)\\
    &= 2\frac{1}{\sqrt{m}}U\Psi\left(\frac{1}{\sqrt{m}}U^{T}w-\beta\right), 
\end{split}
\end{equation}
we obtain from  \eqref{eq:optimalweigth} that 
\begin{equation}
     2\frac{1}{\sqrt{m}}U\Psi\left(\frac{1}{\sqrt{m}}U^{T}w_{*}-\beta\right)  = 0,
\end{equation}
such that
\begin{equation}\label{eq:optimalteachweight}
    w_{*} = (U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta.
\end{equation}

Plugging this expression into the teacher population error \eqref{eq:teacherpopulationerror} we get
\begin{equation}\label{eq:teacherror}
    \mathcal{L}_{\mathrm{TE}} = \langle U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta - \beta, \Psi[U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta -\beta]\rangle
\end{equation}
as claimed.

\label{def:teacher-nu}
For $0<m<\operatorname{rank}(\Psi)$, define $\nu>0$ to be the unique solution of
\begin{equation}\label{eq:nuequation}
    m = \operatorname{tr}\bigl(\Psi(\Psi+\nu I)^{-1}\bigr).
\end{equation}
The solution exists and is unique because the right-hand side is continuous and strictly decreasing in $\nu>0$, from $\operatorname{rank}(\Psi)$ to $0$.

\label{def:deterministic-resolvent}
For the sample covariance matrix
\[
    H=\Psi^{1/2}U_m^{T}U_m\Psi^{1/2},
    \qquad R(z)=(H-zI)^{-1},
\]
define its deterministic resolvent by
\begin{equation}\label{eq:deterministic-resolvent}
    \overline{R}(z)=(-\Psi\kappa(z)-zI)^{-1},
\end{equation}
where $\kappa$ is the analytic solution on the upper half-plane with $\operatorname{Im}\kappa(z)>0$ of
\begin{equation}\label{eq:selfconsistentm}
    -\kappa(z)=\left(1+\frac{1}{m}\operatorname{tr}\bigl(\Psi\overline{R}(z)\bigr)\right)^{-1}.
\end{equation}
We extend this solution to the lower half-plane by complex conjugation. This is the deterministic resolvent associated with the deformed Marchenko--Pastur law (cf.\ Theorem~17 in the notes).

\label{theo:selfconsistenteacher}
With $\nu$ as in Definition~\ref{def:teacher-nu}, the deterministic-equivalent teacher error is
\begin{equation}\label{eq:LTEdetequiv}
    \overline{\mathcal{L}}_{\mathrm{TE}}
    =\nu\langle\Psi^{1/2}\beta,(\Psi+\nu I)^{-1}\Psi^{1/2}\beta\rangle.
\end{equation}

Under our setting, if we define $P_{0}\coloneqq \sum_{\lambda_{j}=0}v_{j}v_{j}^{T}\in \mathbb{R}^{d \times d}$ to be the projection operator onto the zero eigenspace of $\Psi^{\frac{1}{2}}U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi^{\frac{1}{2}}$ we can write
    \begin{equation}
        \mathcal{L}_{\mathrm{ST}}(t) = \left\langle \sqrt{\Psi}\beta, [e^{-2\Psi t}-(I-e^{-\Psi t})^{2}P_{0}+P_{0}(I-e^{-2\Psi t})+P_{0}(I-e^{-\Psi t})^{2}P_{0}]\sqrt{\Psi} \beta\right\rangle.
    \end{equation}

From \eqref{studenttrain} we have that the student neural network  for a time $t>0$ of gradient flow is given by
\begin{equation}
    f_{\mathrm{student}}(t)(\cdot) = \sum_{k= 1}^{d}(1-e^{-\lambda_{k} t})\langle f_{{\mathrm{teacher}}}(\cdot),e_{k}\rangle_{\mathcal{D}}e_{k},
\end{equation}
where $\lambda_{k}$ and $e_{k}$ are the eigenvalues and eigenvectors of the population random-feature kernel induced by the activation function. Thus, we can write the student population error at time $t$ as
\begin{equation}
    \begin{split}
        \mathcal{L}_{\mathrm{ST}}(t) &= \mathbb{E}_{x \sim \mathcal{D}}[(f_{{\mathrm{student}}}(t)-f^{*})^{2}]\\
        &=\mathbb{E}_{x \sim \mathcal{D}}\left[\left(\sum_{k= 1}^{d}(1-e^{-\lambda_{k}t})\langle f_{\mathrm{teacher}},e_{k}\rangle e_{k} - f^{*}\right)^{2}\right].
    \end{split}
\end{equation}
Now, writing $f^{*}=\sum_{k= 1}^{d}\langle f^{*},e_{k}\rangle_{\mathcal{D}}e_{k}$ and using the orthonormality of $\{e_{k}\}_{k=1}^
{d}$, we obtain
\begin{equation}
    \begin{split}
        \mathcal{L}_{\mathrm{ST}}(t) &= \mathbb{E}_{x \sim \mathcal{D}}\left[\left(\sum_{k= 1}^{d}\langle (1-e^{-\lambda_{k}t})f_{\mathrm{teacher}} - f^{*}, e_{k} \rangle_{\mathcal{D}} e_{k}\right)^{2}\right]\\
        &= \mathbb{E}_{x \sim \mathcal{D}}\left[\sum_{k= 1}^{d}\langle(1-e^{-\lambda_{k}t})f_{\mathrm{teacher}}-f^{*}, e_{k}\rangle_{D}^{2}\right]\\
        &=\sum_{k \geq 1}(\mathbb{E}_{x \sim \mathcal{D}}[(1-e^{-\lambda_k t})f_{\mathrm{teacher}}-f^{*}]e_{k})^{2}.
    \end{split}
\end{equation}

Replacing
\begin{equation}
    f_{\mathrm{teacher}}(x) = w_{*}U_{m}x \quad\text{ and }\quad f^{*}(x) = \beta^{T}x
\end{equation}
we get
\begin{equation}\label{eq:intermidiateLST}
    \begin{split}
        \mathcal{L}_{\mathrm{ST}}(t) &= \sum_{k=1}^{d}\left(\mathbb{E}_{x \sim \mathcal{D}}\left[\left((1-e^{-\psi_k t})w_{*}U_{m}x-\beta^{T}x\right)\frac{x_{k}}{\sqrt{\psi_{k}}}\right]\right)^{2}\\
        &= \sum_{k=1}^{d}\left(\mathbb{E}_{x \sim \mathcal{D}}\left[\left((1-e^{-\psi_k t})\sum_{l=1}^{d}(w_{*}U_{m})_{l}x_{l}-\sum_{l=1}^{d}\beta_{l}^{T}x_{l}\right)\frac{x_{k}}{\sqrt{\psi_{k}}}\right]\right)^{2}\\
        &=\sum_{k=1}^{d}\left((1-e^{-\psi_{k}t})(w_{*}U_{m})_{k}\sqrt{\psi_{k}}-\beta_{k}\sqrt{\psi_{k}}\right)^{2}\\
        &= \sum_{k=1}^{d}\psi_{k}((1-e^{-\psi_k}t)(w_{*}U_{m})_{k}-\beta_{k})^{2}.
    \end{split}
\end{equation}
Substituting the optimal weight
\begin{equation}
     w_{*} = (U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta
\end{equation}
in \eqref{eq:intermidiateLST} gives
\begin{equation}
    \mathcal{L}_{\mathrm{ST}}(t) = \langle (I-e^{-\Psi t})[U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta]-\beta, \Psi\{(I-e^{-\Psi t})[U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta]-\beta\}\rangle.
\end{equation}
Now, we can rewrite this error as
\begin{equation}
    \begin{split}
        \mathcal{L}_{\mathrm{ST}}(t) = &\langle (I-e^{-\Psi t})\sqrt{\Psi}U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta\\
        &(I-e^{-\Psi t})\sqrt{\Psi}U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta)\rangle \\
        -&2\langle (I-e^{-\Psi t})\sqrt{\Psi}U_{m}^{T}(U_{m}\Psi U_{m}^{T})^{-1}U_{m}\Psi\beta,\sqrt{\Psi}\beta \rangle \\
        +&\langle \sqrt{\Psi}\beta,\sqrt{\Psi}\beta \rangle,
    \end{split}
\end{equation}
such that 
\begin{equation}
\begin{split}
    \mathcal{L}_{\mathrm{ST}}(t) &= \left\langle (I-e^{-\Psi t})\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^{T}\right)\sqrt{\Psi}\beta, (I-e^{-\Psi t})\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^ {T}\right)\sqrt{\Psi}\beta\right\rangle\\
    &-2\left\langle (I-e^{-\Psi t})\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^{T}\right)\sqrt{\Psi}\beta, \sqrt{\Psi}\beta\right\rangle + \langle \sqrt{\Psi}\beta, \sqrt{\Psi}\beta\rangle\\
    &= \left\langle (I-e^{-\Psi t})\left(\sum_{\tilde{\lambda}_{j}\neq 0} \tilde{v}_{j}\tilde{v}_{j}^{T}\right)\sqrt{\Psi}\beta, \left[(I-e^{-\Psi t})\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^{T}\right)-2I\right]\sqrt{\Psi}\beta\right\rangle + \langle \sqrt{\Psi}\beta,\sqrt{\Psi}\beta\rangle\\
    &= \left\langle \sqrt{\Psi}\beta, \left[\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^{T}\right)(I-e^{-\Psi t})^{2}\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^{T}\right)-2\left(\sum_{\tilde{\lambda}_{j}\neq 0}\tilde{v}_{j}\tilde{v}_{j}^{T}\right)(I-e^{-\Psi t})+I\right]\sqrt{\Psi}\beta\right\rangle.
\end{split}
\end{equation}
Then, using $P_{0}\coloneqq \sum_{\lambda_{j}=0}v_{j}v_{j}^{T}$, the term in square brackets can be rewritten as follows
\begin{equation}
    \begin{split}
        &(I-P_{0})(I-e^{-\Psi t})^{2}(I-P_{0}) - 2(I-P_{0})(I-e^{-\Psi t}) + I\\
        &= (I-e^{-\Psi t})^{2}(I-P_{0}) - P_{0}(I-e^{-\Psi t})^{2}(I-P_{0}) - 2(I-e^{-\Psi t}) + 2P_{0}(I-e^{-\Psi t}) + I\\
        &= (I-e^{-\Psi t})^{2} - (I-e^{-\Psi t})^{2}P_{0} - P_{0}(I-e^{-\Psi t})^{2} + P_{0}(I-e^{-\Psi t})^{2}P_{0} - 2P_{0}(I-e^{-\Psi t}) + I\\
        &= I - 2e^{-\Psi t} + e^{-2\Psi t} - (I-e^{-\Psi t})^{2}P_{0} - P_{0}(I-2e^{-\Psi t}+e^{-2\Psi t})+ P_{0}(I-e^{-\Psi t})^{2}P_{0}\\
        &- 2(I-e^{-\Psi t}) + 2P_{0}(I-e^{-\Psi t}) + I.
    \end{split}
\end{equation}

Thus, we finally obtain
\begin{equation}\label{eq:studentdeteq}
    \mathcal{L}_{\mathrm{ST}}(t) = \left\langle \sqrt{\Psi}\beta, [e^{-2\Psi t}-(I-e^{-\Psi t})^{2}P_{0}+P_{0}(I-e^{-2\Psi t})+P_{0}(I-e^{-\Psi t})^{2}P_{0}]\sqrt{\Psi} \beta\right\rangle
\end{equation}
as we wanted.

\label{theo:doubleresolventapprox}
For $S=(I-e^{-\Psi t})^2$, we have
 egin{equation}
    \overline{\mathcal{P}}(S) =  rac{(I-e^{-\Psi t})^{2}}{(I+\Psi
u^{-1})^{2}} +  rac{ rac{\Psi}{(I+\Psi
u^{-1})^{2}}\operatorname{tr}{\left( rac{
u^{-2}\Psi(I-e^{-\Psi t})^{2}}{(I+\Psi
u^{-1})^{2}}ight)}}{m-\operatorname{tr}{\left( rac{\Psi^{2}
u^{-2}}{(I+\Psi
u^{-1})^{2}}ight)}}
\end{equation}
where $
u$ is the solution of \eqref{eq:nuequation}.

For $\epsilon$ near zero, let us define the following resolvent
    \begin{equation}
        R_{\epsilon}(z)\coloneqq\left(\frac{1}{m}\Psi^{\frac{1}{2}}U^{T}U\Psi^{\frac{1}{2}}+\epsilon S-zI\right)^{-1}
    \end{equation}
    where $S \coloneqq (I-e^{-\Psi t})^{2}$.

    Observe that 
    \begin{equation}\label{eq:derivativein0}
        \partial_{\epsilon}R_{\epsilon}(z)|_{\epsilon=0} = -R_{0}(z)SR_{0}(z),
    \end{equation}
    on the other hand, we also have that
    \begin{equation}
        R_{0}(z) = \sum_{j}\frac{v_{j}v_{j}^{T}}{\lambda_{j}-z}
    \end{equation}
    where $\lambda_{j}$ are the eigenvalues of $H=\frac{1}{m}\Psi^{\frac{1}{2}}U^{T}U\Psi^{\frac{1}{2}}$ and $v_{j}$ are the associated eigenvectors. Thus
    \begin{equation}
    \begin{split}
        R_{0}(z)SR_{0}(z) &= \left(\sum_{j}\frac{v_{j}v_{j}^{T}}{\lambda_{j}-z}\right)S\left(\sum_{k}\frac{v_{k}v_{k}^{T}}{\lambda_{k}-z}\right)\\
        &= \sum_{j,k}(v_{j}v_{j}^{T}Sv_{k}v_{k}^{T})\frac{1}{z^{2}}\left(\frac{1}{1-(\lambda_{j}+\lambda_{k})\frac{1}{z}+\frac{\lambda_{j}\lambda_{k}}{z^{2}}}\right).
    \end{split}
    \end{equation}
    Defining $f(z)=zR_{0}(z)SR_{0}(z)$ and $\Gamma$ a small positively oriented contour around 0 enclosing no nonzero eigenvalues of $H$, consider the integral
    \begin{equation}
        \frac{1}{2\pi i}\oint_{\Gamma}f(z)dz =\frac{1}{2\pi i} \oint_{\Gamma}\sum_{j,k}\frac{v_{j}v_{j}^{T}Sv_{k}v_{k}^{T}}{z}\left(\frac{1}{1-(\lambda_{j}+\lambda_{k})\frac{1}{z}+\frac{\lambda_{j}\lambda_{k}}{z^{2}}}\right)dz  .
    \end{equation}
    If at least one of $\lambda_j$ and $\lambda_k$ is nonzero, the corresponding summand of $f(z)$ is holomorphic inside $\Gamma$ and by Cauchy's theorem its integral is $0$. Thus, only the terms with $\lambda_j=\lambda_k=0$ remain, and we have
    \begin{equation}
        \frac{1}{2\pi i}\oint \sum_{\substack{\lambda_{j}=0 \\ \lambda_{k}=0}}\frac{v_{j}v_{j}^{T}Sv_{k}v_{k}^{T}}{z}dz = P_{0}SP_{0}
    \end{equation}
    since
    \begin{equation}
        \frac{1}{2\pi i}\oint_{\Gamma}\frac{1}{z}dz=1.
    \end{equation}
    Then, we get
    \begin{equation}\label{eq:P0SP0}
        \frac{1}{2\pi i}\oint_{\Gamma}zR_{0}(z)SR_{0}(z)dz = P_{0}SP_{0}.
    \end{equation}


    We now use a linearization procedure to recover the Dyson equation defining $\overline{R}_\epsilon(z)$. We define the larger matrix
    \begin{equation}
        L \coloneqq \begin{pmatrix}
            \epsilon S - zI_{d} & \frac{1}{\sqrt{m}}\Psi^{\frac{1}{2}}U^{T}\\
            \frac{1}{\sqrt{m}}U\Psi^{\frac{1}{2}} & -I_{m}
        \end{pmatrix} \in \mathbb{C}^{(d+m)\times(d+m)}.
    \end{equation}
    Using the Schur complement formula, we obtain
    \begin{equation}
    (L^{-1})_{11} = \left(\frac{1}{m}\Psi^{\frac{1}{2}}U^{T}U\Psi^{\frac{1}{2}}+\epsilon S -zI\right)^{-1}.
    \end{equation}
    Now, by the Dyson equation
    \begin{equation}
    \begin{split}
        \begin{pmatrix}
            \mathcal{M}_{11} & 0\\
            0 & \mathcal{M}_{22}
        \end{pmatrix}\left(\begin{pmatrix}
            \epsilon S - zI & 0\\
            0 & -I_{m}
        \end{pmatrix}-\begin{pmatrix}
            \frac{1}{m}\Psi \operatorname{tr}{(\mathcal{M}_{22})} & 0\\
            0 & \frac{1}{m}\operatorname{tr}{(\mathcal{M}_{11}\Psi)}I_{m}
        \end{pmatrix}\right) =\begin{pmatrix}
            I & 0\\
            0 & I_{m}
        \end{pmatrix},
    \end{split}
    \end{equation}
    we get
    \begin{equation}\label{eq:mathcaldef}
    \begin{split}
        \mathcal{M}_{11} &= \left(\epsilon S - zI -\frac{1}{m}\Psi\operatorname{tr}{(\mathcal{M}_{22})}\right)^{-1}\\
        \mathcal{M}_{22} &= \left(-1-\frac{1}{m}\operatorname{tr}{(\mathcal{M}_{11}\Psi)}\right)^{-1}I_m
    \end{split}
    \end{equation}
    and $\mathcal{M}_{11}=\overline{R}_\epsilon(z)$ is exactly the matrix in Definition~\ref{def:perturbed-resolvent}.
    In our case, $S=(I-e^{-\Psi t})^{2}$ and $\Psi$ share the same orthonormal basis of eigenvectors $\{w_{j}\}$. Let $\lambda_{j}^{S}$ and $\lambda_{j}^{\Psi}$ be the associated eigenvalues, then
    \begin{equation}
    \begin{split}
        \langle w_{j}, \mathcal{M}_{11}w_{j}\rangle = \left(\epsilon\lambda_{j}^{S}-z-\frac{\lambda_j^\Psi}{m}\operatorname{tr}(\mathcal{M}_{22})\right)^{-1}\\
        \mathcal{M}_{22} = \left(-1-\frac{1}{m}\operatorname{tr}{(\mathcal{M}_{11}\Psi)}\right)^{-1}I_m.
    \end{split}
    \end{equation}
    To ease notation in the calculation below, write $\kappa(z)=\kappa_\epsilon(z)$, suppressing its dependence on $\epsilon$. Then
    \begin{equation}
        \kappa(z) = \frac{1}{m}\operatorname{tr}{(\mathcal{M}_{22})},
    \end{equation}
    then 
    \begin{equation}\label{eq:mathcal11}
        \langle w_{j}, \mathcal{M}_{11} w_{j}\rangle = \frac{1}{\epsilon \lambda_{j}^{S}-z-\lambda_{j}^{\Psi}\kappa(z)}.
    \end{equation}
    Note that 
    \begin{equation}
        \operatorname{tr}{(\mathcal{M}_{22})} = m\left(-1-\frac{1}{m}\operatorname{tr}{(\mathcal{M}_{11}\Psi)}\right)^{-1}
    \end{equation}
    such that by \eqref{eq:mathcaldef} we have
    \begin{equation}
        \kappa(z)= \frac{1}{-1-\frac{1}{m}\sum_{j=1}^{d}\langle w_{j},\mathcal{M}_{11}w_{j}\rangle \lambda_{j}^{\Psi}}.
    \end{equation}
    Also, from \eqref{eq:mathcal11} we get
    \begin{equation}
        \mathcal{M}_{11} =\sum_{j=1}^{d}w_{j}w_{j}^{T}\left(\frac{1}{\epsilon \lambda_{j}^{S}-z-\lambda_{j}^{\Psi}\kappa(z)}\right),
    \end{equation}
    such that we have the following scalar self-consistent equation
    \begin{equation}
        \kappa(z) = \frac{1}{-1-\frac{1}{m}\sum_{j=1}^{d}\frac{\lambda_{j}^{\Psi}}{\epsilon\lambda_{j}^{S}-z-\lambda_{j}^{\Psi}\kappa(z)}}.
    \end{equation}
    The exact identities \eqref{eq:derivativein0} and \eqref{eq:P0SP0} motivate the definitions of $\overline{Q}_S$ and $\overline{\mathcal{P}}(S)$. Since $\mathcal{M}_{11}=\overline{R}_\epsilon$, Definition~\ref{def:perturbed-resolvent} gives
    \begin{equation}
        \overline{\mathcal{P}}(S) = -\frac{1}{2\pi i} \oint_{\Gamma}z \left.\frac{\partial \mathcal{M}_{11}}{\partial \epsilon}\right|_{\epsilon=0}\;dz.
    \end{equation}
    Calculating, we get
    \begin{equation}
        \frac{\partial\mathcal{M}_{11}}{\partial\epsilon} =-\sum_{j=1}^{d}\frac{w_{j}w_{j}^{T}}{(\epsilon\lambda_{j}^{S}-z-\lambda_{j}^{\Psi}\kappa(z))^{2}}\left(\lambda_{j}^{S}-\lambda_{j}^{\Psi}\frac{\partial \kappa(z)}{\partial \epsilon}\right).
    \end{equation}
    Also,
    \begin{equation}
    \begin{split}
        \frac{\partial \kappa(z)}{\partial \epsilon} = \frac{-1}{\left(-1-\frac{1}{m}\sum_{j=1}^{d}\frac{\lambda_{j}^{\Psi}}{\epsilon\lambda_{j}^{S}-z-\lambda_{j}^{\Psi}\kappa(z)}\right)^{2}}\left(\frac{1}{m}\sum_{j=1}^{d}\frac{\lambda_{j}^{\Psi}(\lambda_{j}^{S}-\lambda_{j}^{\Psi}\frac{\partial \kappa(z)}{\partial \epsilon})}{(\epsilon\lambda_{j}^{S}-z-\lambda_{j}^{\Psi}\kappa(z))^{2}}\right),
    \end{split}
    \end{equation}
    such that 
    \begin{equation}
        \left.\frac{\partial \kappa(z)}{\partial \epsilon}\right|_{\epsilon=0} =\left. \frac{-\frac{1}{m}\operatorname{tr}{\left(\frac{\kappa(z)^2\Psi S}{(z+\Psi\kappa(z))^{2}}\right)}}{1-\frac{1}{m}\operatorname{tr}{\left(\frac{\Psi^{2}\kappa(z)^{2}}{(z+\Psi\kappa(z))^{2}}\right)}}\right|_{\epsilon=0}.
    \end{equation}
    Then    \begin{equation}\label{eq:finaldoubleresolvent}
            \overline{\mathcal{P}}(S)
            = \frac{1}{2\pi i}\oint_{\Gamma}\sum_{j=1}^{d}\frac{zw_{j}w_{j}^{T}}{(z+\lambda_{j}^{\Psi}\kappa(z))^{2}}\left[\lambda_{j}^{S}+\frac{\frac{\lambda_{j}^{\Psi}}{m}\operatorname{tr}{\left(\frac{\kappa(z)^{2}\Psi (I-e^{-\Psi t})^{2}}{(z+\Psi\kappa(z))^{2}}\right)}}{1-\frac{1}{m}\operatorname{tr}{\left(\frac{\Psi^{2}\kappa(z)^{2}}{(z+\Psi\kappa(z))^{2}}\right)}}\right]_{\epsilon=0} \;dz.
    \end{equation}
    At $\epsilon=0$, the proof of Theorem \ref{theo:selfconsistenteacher} gives $\kappa(z)=cz+O(z^2)$ with $c=\nu^{-1}$. Observe also that the denominator at zero is strictly positive:
    \[
        m-\operatorname{tr}\left(\frac{c^2\Psi^2}{(I+c\Psi)^2}\right)
        =\operatorname{tr}\left(\frac{c\Psi}{(I+c\Psi)^2}\right)>0,
    \]
    where we used \eqref{eq:nuequation}. Thus, keeping the coefficient of $z^{-1}$ in the integrand, we can rewrite \eqref{eq:finaldoubleresolvent} as follows 
    \begin{equation}\label{eq:double-resolvent-two-term}
        \begin{split}
            \overline{\mathcal{P}}(S)&= \frac{1}{2\pi i}\oint_{\Gamma}\sum_{j=1}^{d}\frac{w_{j}w_{j}^{T}}{z(1+\Psi_{j}c)^{2}} \left[(1-e^{-\Psi_{j}t})^{2}+\frac{\frac{\Psi_{j}}{m}\operatorname{tr}{\left(\frac{c^2\Psi(I-e^{-\Psi t})^{2}}{(I+\Psi c)^{2}}\right)}}{1-\frac{1}{m}\operatorname{tr}{\left(\frac{\Psi^{2}c^{2}}{(I+\Psi c)^{2}}\right)}}\right]dz\\
            &= \frac{(I-e^{-\Psi t})^{2}}{(I+\Psi c)^{2}} + \frac{\frac{\Psi}{(I+\Psi c)^{2}}\operatorname{tr}{\left(\frac{c^{2}\Psi(I-e^{-\Psi t})^{2}}{(I+\Psi c)^{2}}\right)}}{m-\operatorname{tr}{\left(\frac{\Psi^{2}c^{2}}{(I+\Psi c)^{2}}\right)}}
        \end{split}
    \end{equation}
as claimed.

\label{def:student-error-de}
Let $S_t=(I-e^{-\Psi t})^2$. Replacing the single-projector terms and the double-projector term in \eqref{eq:studentdeteq} by their deterministic counterparts, define
\begin{equation}\label{eq:student-error-de}
    \overline{\mathcal{L}}_{\mathrm{ST}}(t)\coloneqq\big\langle\Psi^{1/2}\beta,\big[e^{-2\Psi t}-S_t\overline{P}_0+\overline{P}_0(I-e^{-2\Psi t})+\overline{\mathcal{P}}(S_t)\big]\Psi^{1/2}\beta\big\rangle,
\end{equation}
where $\overline{P}_0=\nu(\Psi+\nu I)^{-1}$ and $\overline{\mathcal{P}}(S_t)$ is evaluated in Theorem~\ref{theo:doubleresolventapprox}.

We have
    \begin{equation}
       \left. \frac{d^{k-2}}{dt^{k-2}}(1-t^{2})^{k+\frac{d-3}{2}} \right|_{t=0}^{t=1} = \begin{cases}
           (-1)^{\frac{k}{2}}\binom{k+\frac{d-3}{2}}{\frac{k-2}{2}}(k-2)!,\; \text{$k$ even}\\
           0,\; \text{$k$ odd}
       \end{cases}
    \end{equation}

Using the generalized binomial theorem and denoting $a \coloneqq k+\frac{d-3}{2}$ we have that for $t=0$
    \begin{equation}
        (1-t^{2})^{a} = \sum_{l=0}^{\infty} \binom{a}{l} (-1)^{l}t^{2l}
    \end{equation}.

    If $2l<k-2$, the $(k-2)-$th derivative is $0$ because it is the derivative of a constant. If $2l>k-2$, the $(k-2)-$th derivative is also $0$ since we will have $t^{s}$ for $s>0$ evaluated at $t=0$. We conclude
    \begin{equation}
    \begin{split}
        -\frac{d^{k-2}}{dt^{k-2}}(1-t^{2})^{a} &= -\binom{a}{\frac{k-2}{2}}(-1)^{\frac{k-2}{2}}\left[2\left(\frac{k-2}{2}\right)\right]!\\
        &= \binom{a}{\frac{k}{2}}(-1)^{\frac{k-2}{2}}\left(k-2\right)!
    \end{split}
    \end{equation}

    Since we only have the term $2l=k-2$ we necessarily have that $k$ is even. Moreover, for $t-1$, we observe that all terms in $\frac{d^{k-2}}{dt^{k-2}}$ will contain a factor of $(1-t^{2})^{\frac{d-3}{2}+b}$ where $b\geq 2$ such that in $t=1$ this will be evaluated to be zero. This concludes the proof.

For $d\gg 1$ and $k\geq 2$ we have the asymptotics
\begin{equation}
    N_k \sigma_k^2
    \asymp
    \begin{cases}
        \displaystyle
        \frac{\sqrt{d}\,\;(2k+d)}
        {2^k k! (d+k)^{5/2}},\;
        & \text{if } k=2,\; \\[6pt]
        \displaystyle
        \frac{\sqrt{d}\,\;(2k+d)}
        {2^k k! (d+k)^{5/2}}
        \left[
            (k-2)(k-3)\cdots\left(\frac{k}{2}\right)
        \right]^2,\;
        & \text{if } k>2.
    \end{cases}
\end{equation}

Since we are always considering the setting where $d\gg 1$ we can use the asymptotics of the Gamma function to get the following simplication
\begin{equation}
    \frac{\Gamma\left(\frac{d}{2}\right)}{\sqrt{\pi}\Gamma\left(\frac{d-1}{2}\right)} = \frac{\Gamma(\frac{d-1}{2}+\frac{1}{2})}{\sqrt{\pi}\Gamma\left(\frac{d-1}{2}\right)} \asymp \frac{\Gamma\left(\frac{d-1}{2}\right)\left(\frac{d-1}{2}\right)^{\frac{1}{2}}}{\sqrt{\pi}\Gamma\left(\frac{d-1}{2}\right)} \asymp \sqrt{d}
\end{equation}
and
\begin{equation}
    \frac{\Gamma\left(\frac{d-1}{2}\right)}{\Gamma\left(\frac{d-1}{2}+k\right)}=\frac{1}{\left(\frac{d-1}{2}+(k-1)\right)...\left(\frac{d-1}{2}\right)}.
\end{equation}

Putting everything together we obtain the following expression for $\sigma_{k}$ when $k>1$ in the regime where $d$ is very large
\begin{equation}\label{eq:sigmakasymp}
    \sigma_{k} \asymp \frac{(-1)^{\frac{k}{2}+1}}{2^{k}} \frac{\sqrt{d}}{\left(\frac{d-1}{2}+(k-1)\right)...\left(\frac{d-1}{2}\right)}\binom{k+\frac{d-3}{2}}{\frac{k-2}{2}}(k-2)!
\end{equation}
for $k>1$ even and $\sigma_{k}=0$ for $k>1$ odd.

Using \eqref{eq:Nkfinal} and \eqref{eq:sigmakasymp} we conclude that for $k>1$ even
\begin{equation}
\begin{split}
    N_{k}\sigma_{k}^{2} &\asymp \frac{(2k+d-2)(d-2+(k-1))(d-2+(k-2))...(d-1)}{k!}\\
    &\cdot\frac{d}{4^k}\frac{1}{\left(\frac{d-1}{2}+(k-1)\right)^2\left(\frac{d-1}{2}+(k-2)\right)^2...\left(\frac{d-1}{2}\right)^2}\left(\frac{(k+\frac{d-3}{2})!}{\left(\frac{k+d-1}{2}\right)!\left(\frac{k-2}{2}\right)!}\right)^2((k-2)!)^2
\end{split}
\end{equation}

Observing that
\begin{equation}
    \left(\frac{d-1}{2}+(k-1)\right)\left(\frac{d-1}{2}+ (k-2)\right)...\left(\frac{d-1}{2}\right) = \frac{\left(k+\frac{d-3}{2}\right)!}{\left(\frac{d-3}{2}\right)!}
\end{equation}
we get
\begin{equation}\label{eq:Nsigma}
    \begin{split}
        N_{k}\sigma_{k}^{2} &\asymp \frac{(2k+d-2)(d-2+ (k-1))(d-2+(k-2))...(d-1)}{k!}\\
        &\cdot\frac{d}{4^k}\left(\frac{\left(\frac{d-3}{2}\right)!\left(k-2\right)!}{\left(\frac{k+d-1}{2}\right)!\left(\frac{k-2}{2}\right)!}\right)^{2}.
    \end{split}
\end{equation}

Notice that
\begin{equation}
