        &= (d+k-3)(d+k-4)...\left(\frac{d+k+1}{2}\right)
    \end{split}
\end{equation}
also
\begin{equation}
    \frac{(k-2)!}{\left(\frac{k-2}{2}\right)!} = \begin{cases}
        (k-2)(k-3)...\left(\frac{k}{2}\right),\; \text{if $k>2$}\\
        1,\; \text{if $k=2$}. 
    \end{cases}
\end{equation}
such that substituting in the expression for $N_{k}\sigma_{k}^{2}$ and separating the terms depending only on $k$, only on $d$ or on both, we get for $k> 2$ even
\begin{equation}
    \begin{split}
        N_{k}\sigma_{k}^{2} &\asymp \frac{(2k+d-2)(d+k-3)(d+k-4)...(\frac{d+k+1}{2})}{\left(\frac{k+d-1}{2}\right)!}\\
        &\cdot \frac{d\left[\left(\frac{d-3}{2}\right)!\right]^{2}}{(d-2)!} \frac{[(k-2)(k-3)...(\frac{k}{2})]^2}{4^k k!}
    \end{split}
\end{equation}
 and for $k=2$
\begin{equation}
    \begin{split}
        N_{k}\sigma_{k}^{2} &\asymp \frac{(2k+d-2)(d+k-3)(d+k-4)...(\frac{d+k+1}{2})}{\left(\frac{k+d-1}{2}\right)!}\frac{d\left[\left(\frac{d-3}{2}\right)!\right]^{2}}{(d-2)!4^k k!}.
    \end{split}
\end{equation}


Now, since $d$ is very large we will use Stirling approximation on the terms that contains only $d$ or that contains both as follows
\begin{equation}
\begin{split}
    \frac{d\left[\left(\frac{d-3}{2}\right)\right]^{2}}{(d-2)!} &\asymp \frac{d\left[\left(\frac{d-3}{2}\right)^{\frac{1}{2}}\left(\frac{d-3}{2e}\right)^{\frac{d-3}{2}}\right]^{2}}{(d-2)^{\frac{1}{2}}(\frac{d-2}{e})^{d-2}}\\
    &\asymp \frac{d \cdot d^{1+d-3}}{d^{\frac{1}{2}+d-2}}\frac{e^{d-2}}{(2e)^{d-3}} \asymp \frac{d^{\frac{1}{2}}}{2^{d}}
