\end{equation}
and
\begin{equation}
    \begin{split}
        \frac{(2k+d-2)(d+k-3)(d+k-4)...\left(\frac{d+k+1}{2}\right)}{\left(\frac{k+d-1}{2}\right)!}
        &\asymp \frac{(2k+d-2)(d+k-3)!}{[\left(\frac{d+k-1}{2}\right)]^{2}} \\
        &\asymp \frac{(2k+d)(d+k-3)^{\frac{1}{2}}\left(\frac{d+k-3}{e}\right)^{d+k-3}}{\left[\left(\frac{d+k-1}{2}\right)^{\frac{1}{2}}\left(\frac{d+k-1}{2e}\right)^{\frac{d+k-1}{2}}\right]^{2}}\\
        &\asymp (2k+d)(d+k)^{-\frac{5}{2}}2^{d+k}.
    \end{split}
\end{equation}

Putting it all together we get 
\begin{equation}\label{eq:Nksigmak2expression}
    N_k \sigma_k^2
    \asymp
    \begin{cases}
        \displaystyle
        \frac{\sqrt{d}\,\;(2k+d)}
        {2^k k! (d+k)^{5/2}},\;
        & \text{if } k=2,\; \\[6pt]
