as we wanted.

\label{lem:nu-relu}
    Under our setting, we have 
    \begin{equation}
    \nu = \Theta(d^{-\alpha-1}).
\end{equation}

We use again \eqref{eq:nuequation} from Theorem \ref{theo:selfconsistenteacher}, that is,
\begin{equation}
    m = \operatorname{tr}{\left(\Psi(\Psi+\nu)^{-1}\right)}
\end{equation}
where now $m=M_{\mathrm{TE}}=d^{\alpha}$.

Calculating
\begin{equation}
    d^{\alpha} = \operatorname{tr}{\left(\frac{\Psi}{\Psi+\nu}\right)} = \sum_{k\in \mathcal{K}}\frac{N_{k}\sigma_{k}^{2}}{\sigma_{k}^{2}+\nu}.
\end{equation}
since the eigenvalues of $\Psi$ are $\sigma_{k}^{2}$ and there are $N_{k}$ of them. 

We want to find upper and lower bounds for $\nu$ to find its order of magnitude with respect to $d$ in the regime where $d$ is very large. Let us separate the terms for $k=1$ and $k=2$ from the summation to get
\begin{equation}
    d^{\alpha} = \frac{N_{0}\sigma_{0}^{2}}{\sigma_{0}^{2}+\nu} + \frac{N_{1}\sigma_{1}^{2}}{\sigma_{1}^{2}+\nu} +  \frac{N_{2}\sigma_{2}^{2}}{\sigma_{2}^{2}+\nu} + \sum_{\substack{k\in \mathcal{K}\\ k \geq 4}}\frac{N_{k}\sigma_{k}^{2}}{\sigma_{k}^{2}+\nu}
\end{equation}

For $k=0$, we get
\begin{equation}
    \frac{N_{0}\sigma_{0}^{2}}{\sigma_{0}^{2}+\nu} \asymp \frac{d^{-1}}{d^{-1}+\nu} = \frac{1}{1+d\nu}.
\end{equation}

For $k=1$, using \eqref{eq:sigma1} and \eqref{eq:N1sigma1squared} we obtain
\begin{equation}
\begin{split}
    \frac{N_{1}\sigma_{1}^{2}}{\sigma_{1}^{2}+\nu} &= \frac{\frac{1}{4d}}{\left(\frac{1}{2d}\right)^{2}+\nu}\\
    &= \frac{4d^{2}}{1+4d^{2}\nu}\frac{1}{4d}\\
    &= \frac{d}{1+4d^{2}\nu}.
\end{split}
\end{equation}

Now, for $k=2$ we use \eqref{eq:Nksigmak2expression} and \eqref{eq:sigma2} to get
\begin{equation}
    \frac{N_{2}\sigma_{2}^{2}}{\sigma_{2}^{2}+\nu} = \frac{\sqrt{d}(4+d)}{8(d+2)^{\frac{5}{2}}}\frac{1}{\frac{e^{2}}{4}d^{d-1}(d+2)^{-d-2}+\nu}
\end{equation}

Finally, for the $k\geq 4$ even
\begin{equation}\label{eq:sumkgeq4}
\begin{split}
    \sum_{\substack{k\in \mathcal{K}\\ k \geq 4}} \frac{N_{k}\sigma_{k}^{2}}{\sigma_{k}^{2}+\nu} 
    &= \frac{\sqrt{d}(2k+d)[(k-2)(k-3)...(k/2)]^{2}}{2^{k}k!(d+k)^{\frac{5}{2}}\left[\frac{d^{d-1}e^{k}}{(d+k)^{d+k}2^{k}}[(k-2)(k-3)...(k/2)]^{2}+\nu\right]}\\
    &= \frac{\sqrt{d}(2k+d)[(k-2)(k-3)...(k/2)]^{2}}{k!(d+k)^{\frac{5}{2}-d-k}d^{d-1}e^{k}[(k-2)(k-3)...(k/2)]^{2} + 2^{k}k!(d+k)^{\frac{5}{2}}\nu}\\
    &= \frac{\sqrt{d}(2k+d)(d+k)^{d+k}[(k-2)(k-3)...(k/2)]^{2}}{k!(d+k)^{\frac{5}{2}}d^{d-1}e^{k}[(k-2)(k-3)...(k/2)]^{2} + 2^{k}k!(d+k)^{d+k+\frac{5}{2}}\nu}.
\end{split}
\end{equation}

\noindent\textbf{Upper bound on $\nu$.} In this case we argue that the summation in $k$ is not large. 

Ignoring some positive terms in the denominators we can bound
\begin{equation}\label{eq:d2k0equation}
\begin{split}
    d^{\alpha} &\lesssim \frac{1}{d\nu}+ \frac{d}{4d^{2}\nu} + \frac{\sqrt{d}(4+d)}{8(d+2)^{\frac{5}{2}}\nu} + \sum_{\substack{k\in \mathcal{K}\\ k \geq 4}}\frac{\sqrt{d}(2k+d)[(k-2)(k-3)...(\frac{k}{2})]^{2}}{2^k k!(d+k)^{\frac{5}{2}}\nu}\\
    &\lesssim \frac{1}{d\nu} + \frac{1}{4d\nu} + \frac{1}{4d\nu} + \frac{\sqrt{d}}{d^{\frac{3}{2}}\nu}\sum_{\substack{k\in \mathcal{K}\\ k \geq 4}}\frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!}.
\end{split}
\end{equation}

The following claim states that the terms in the summation are not very large and that they actually decrease in $k$.

\begin{claim}
    If $k\geq 4$ is an even number, then
    \begin{equation}
        \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} \leq \frac{1}{2k(k-1)}.
    \end{equation}
\end{claim}

\begin{proofclaim}
    We have
    \begin{equation}
        \begin{split}
            \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} &= \frac{[(k-2)!/(k/2 -1)!]^{2}}{k(k-1)(k-2)!2^{k-1}}\\
            &= \frac{(k-2)!}{(k/2-1)!k(k-1)2^{k-1}}.
        \end{split}
    \end{equation}
    Now, write $k=2l$ for $l\in \mathbb{N}$ and $l\geq2$ to get
    \begin{equation}
        \begin{split}
            \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} &= \frac{(2l-2)!}{[(l-1)!]^{2}}\frac{1}{2l(2l-1)2^{2l-1}}\\
            &= \binom{2l-2}{l-1}\frac{1}{2l(2l-1)2^{2l-1}}.
        \end{split}
    \end{equation}

Now, we use that
\begin{equation}
    \binom{2l-2}{l-1} \leq \sum_{i=0}^{2l-2}\binom{2l-2}{i} = 2^{2l-2}
\end{equation}
since it is the number of subsets of a set of $2l-2$ elements. This gives
\begin{equation}
    \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} \leq \frac{2^{2l-2}}{2l(2l-1)2^{2l-1}} = \frac{1}{2k(k-1)}
\end{equation}
as we wanted. \hfill \ensuremath{\blacksquare}
\end{proofclaim}

Using the previous claim in \eqref{eq:d2k0equation} we get
\begin{equation}
    d^{\alpha} \lesssim \frac{1}{d\nu} +  \frac{1}{2d\nu} + \frac{1}{d\nu}\sum_{\substack{k\in \mathcal{K}\\ k \geq 4}}\frac{1}{2k(k-1)}
    \asymp \frac{1}{d\nu}
\end{equation}
since the sum is convergent.

We conclude that
\begin{equation}
    \nu \lesssim d^{-\alpha-1}.
\end{equation}

\noindent\textbf{Lower bound on $\nu$.} We have
\begin{equation}
    d^{\alpha} \asymp \sum_{k\in \mathcal{K}}\frac{N_{k}\sigma_{k}^{2}}{\sigma_{k}^{2}+\nu}
\end{equation}
such that ignoring all terms in the sum except the term with $k=k_{\alpha}$ being any even fixed integer with $k>\alpha$  Since all the terms in the sum are positive, we get
\begin{equation}
    d^{\alpha}\gtrsim\frac{N_{k_{\alpha}}\sigma_{k_{\alpha}}^{2}}{\sigma_{k_{\alpha}}^{2}+\nu}.
\end{equation}
Since $\alpha=O(1)$, we can choose $k_{\alpha}=O(1)$ and use from \eqref{eq:Nkasymptotics}, \eqref{eq:sigmakasymptotics}, and \eqref{eq:sigma2}  that
\begin{equation}
    N_{k_{\alpha}}\asymp d^{k_{\alpha}},
    \qquad
    \sigma_{k_{\alpha}}^{2}\asymp d^{-k_{\alpha}-1}.
\end{equation}
Thus,
\begin{equation}
    d^{\alpha}
    \gtrsim
    \frac{d^{k_{\alpha}}d^{-k_{\alpha}-1}}{d^{-k_{\alpha}-1}+\nu}
    =
    \frac{d^{-1}}{d^{-k_{\alpha}-1}+\nu}.
\end{equation}
It follows that
\begin{equation}
    d^{-k_{\alpha}-1}+\nu\gtrsim d^{-\alpha-1}.
\end{equation}
Since $k_{\alpha}>\alpha$, we have
\begin{equation}
    d^{-k_{\alpha}-1}=o(d^{-\alpha-1}),
\end{equation}
and therefore, for $d$ large enough,
\begin{equation}
    \nu \gtrsim d^{-\alpha-1}.
\end{equation}

Together with the upper bound we obtain
\begin{equation}
    \nu = \Theta(d^{-\alpha-1}).
\end{equation}
as claimed.

If $k\geq 4$ is an even number, then
    \begin{equation}
        \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} \leq \frac{1}{2k(k-1)}.
    \end{equation}

We have
    \begin{equation}
        \begin{split}
            \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} &= \frac{[(k-2)!/(k/2 -1)!]^{2}}{k(k-1)(k-2)!2^{k-1}}\\
            &= \frac{(k-2)!}{(k/2-1)!k(k-1)2^{k-1}}.
        \end{split}
