        \begin{split}
            \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k-1}k!} &= \frac{(2l-2)!}{[(l-1)!]^{2}}\frac{1}{2l(2l-1)2^{2l-1}}\\
            &= \binom{2l-2}{l-1}\frac{1}{2l(2l-1)2^{2l-1}}.
        \end{split}
    \end{equation}

Now, we use that
\begin{equation}
    \binom{2l-2}{l-1} \leq \sum_{i=0}^{2l-2}\binom{2l-2}{i} = 2^{2l-2}
\end{equation}
since it is the number of subsets of a set of $2l-2$ elements. This gives
