\end{equation}
as we wanted. \hfill \ensuremath{\blacksquare}

\label{theorem:teachererror}
        In our setting of a pure harmonic target of degree $k_{0}\geq1$ with $\lVert f^{*}\rVert_{\mathcal{D}}=1$, if $M_{\mathrm{TE}} = d^{\alpha}$ for some $\alpha>0$, then
\begin{equation}
    \overline{\mathcal{L}}_{\mathrm{TE}} \asymp \begin{cases}
       1,\; \alpha \in (0,\;k_{0}]\\
        d^{-\alpha+k_{0}},\; \alpha > k_{0}.
    \end{cases}
\end{equation}

We have the same expression for the teacher deterministic equivalent error as the one for the linear case
\begin{equation}
    \overline{\mathcal{L}}_{\mathrm{TE}} = \nu \langle \Psi^{\frac{1}{2}}\beta, (\Psi+\nu)^{-1}\Psi^{\frac{1}{2}}\beta\rangle. 
\end{equation}

Notice that for all $k\leq k_{0}$ where $k_{0}=O(1)$ and $d\gg 1$ we get from \eqref{eq:Nkasymptotics}, \eqref{eq:sigmakasymptotics}, and \eqref{eq:sigma2} that
\begin{equation}\label{eq:sigmaNapprox}
\begin{split}
    N_{k} &\asymp d^{k}\\
    \sigma_{k}^{2} &\asymp d^{-k-1}
\end{split}
\end{equation}
for $k=1$ or $k$ even. This is also true for $k=0$ from equation \eqref{eq:sigma0} and $N_{0}=1$.

The unit norm hypothesis for the target gives
\begin{equation}
    \sum_{k\in \mathcal{K}}\sum_{l=1}^{N_{k}} \sigma_{k}^{2}\beta_{k,l}^{2} = 1.
\end{equation}

We obtain
\begin{equation}\begin{split}
    \overline{\mathcal{L}}_{\mathrm{TE}} &= \nu \langle \Psi^{\frac{1}{2}}\beta, (\Psi+\nu)^{-1}\Psi^{\frac{1}{2}}\beta \rangle\\
    &= \nu \sum_{k\in \mathcal{K}}\frac{\sigma_{k}^{2}}{\sigma_{k}^{2}+\nu} \sum_{l=1}^{N_{k}}\beta_{k,l}^{2}\\
    &\asymp d^{-\alpha-1} \sum_{k\in \mathcal{K}}\frac{d^{-k-1}}{d^{-k-1}+d^{-\alpha-1}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2} 
\end{split}
\end{equation}

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}
    \overline{\mathcal{L}}_{\mathrm{TE}} \asymp d^{-\alpha-1} \left\{\sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq \alpha}} \frac{d^{-k-1}}{d^{-k-1}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2} + \sum_{\substack{k\in \mathcal{K}\\ \alpha+1 \leq k \leq k_{0}}}\frac{d^{-k-1}}{d^{-\alpha-1}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}\right\}
\end{equation}
using $\beta_{k,l}^{2}\neq 0$ only for $k=k_{0}$, i.e., the pure harmonic target hypothesis, we get
\begin{equation}\begin{split}
    \overline{\mathcal{L}}_{\mathrm{TE}} &\asymp d^{-\alpha -1}\frac{d^{-k_{0}-1}}{d^{-\alpha -1}}\sum_{l=1}^{N_{k_{0}}}\beta_{k_{0},l}^{2}\\
    &\asymp 1.
\end{split}
\end{equation}

\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\begin{split}
    \overline{\mathcal{L}}_{\mathrm{TE}} &\asymp d^{-\alpha -1} \frac{d^{-k_{0}-1}}{d^{-k_{0}-1}} \sum_{l=1}^{N_{k_{0}}}\beta_{k_{0},l}^{2}\\
    &\asymp d^{-\alpha +k_{0}}.
\end{split}
\end{equation}

In conclusion we obtained
\begin{equation}\label{eq:teacherreluerror}
    \overline{\mathcal{L}}_{\mathrm{TE}} \asymp \begin{cases}
        1,\; \text{ if $\alpha \in (0,\;k_{0}]$},\;\\
        d^{-\alpha+k_{0}},\; \text{ if $\alpha > k_{0}$}
    \end{cases}
\end{equation}
as we desired.

Under the unit norm hypothesis $\lVert f^{*}\rVert_{\mathcal{D}}=1$, we start with \eqref{eq:studentdeteq} that gives the student deterministic equivalent error at $t=T$, with $\overline{P}_0=\nu(\Psi+\nu I)^{-1}$ and $S_T=(I-e^{-\Psi T})^2$,
 \begin{equation}
    \overline{\mathcal{L}}_{\mathrm{ST}}(T) = \langle \Psi^{\frac{1}{2}}\beta, [e^{-2\Psi T}-S_T\overline{P}_0+\overline{P}_0(I-e^{-2\Psi T})+\overline{\mathcal{P}}(S_T)]\Psi^{\frac{1}{2}}\beta\rangle.
\end{equation}

We use the stopping-time from the statement of Theorem \ref{theo:weaktostrongrelu}, that is,
\begin{equation}
\begin{split}
    T &= \frac{1}{\sigma_{k_{0}}^{2}}(\log{M}_{\mathrm{TE}}+\log{\overline{\mathcal{L}}_{\mathrm{TE}}^{-1}}),
\end{split}
\end{equation}
such that, using \eqref{eq:teacherreluerror} we get
\begin{equation}
    T \asymp \begin{cases}
    d^{k_{0}+1}\log{(d^{\alpha})},\; \text{ if $\alpha \in (0,\;k_{0}]$}\\
    d^{k_{0}+1}\log{(d^{2\alpha-k_{0}})},\; \text{ if $\alpha > k_{0}$}.
    \end{cases}
\end{equation}

We treat each of the four terms of $\overline{\mathcal{L}}_{\mathrm{ST}}(T)$ above separately. Since $\beta_{0,l}=0$ for all $l$, we do not write $k=0$ in the index summations below when $\beta$ is in the sum. 

\noindent\textbf{Term 1:} 
$\langle \Psi^{\frac{1}{2}}\beta, e^{-2\Psi T}\Psi^{\frac{1}{2}}\beta\rangle$

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}\label{eq:student1alpha1}
\begin{split}
    1) \coloneqq \langle \Psi^{\frac{1}{2}}\beta, e^{-2\Psi T}\Psi^{\frac{1}{2}}\beta\rangle &= \sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}}\frac{\sigma_{k}^{2}}{e^{2\sigma_{k}^{2}T}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}\\ 
    &\asymp \frac{\sigma_{k_{0}}^{2}\sum_{l=1}^{N_{k_{0}}}\beta_{k_{0},l}^{2}}{\exp{(2\sigma_{k_{0}}^{2}\sigma_{k_{0}}^{-2}\log{(d^{\alpha})})}}\\
    &\asymp \frac{1}{d^{2\alpha}}\\
    &\asymp d^{-2\alpha} 
\end{split}
\end{equation}

\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\label{eq:student1alpha2}
    \begin{split}
    1) = \langle \Psi^{\frac{1}{2}}\beta, e^{-2\Psi T}\Psi^{\frac{1}{2}}\beta\rangle &\asymp \frac{1}{d^{4\alpha-2k_{0}}}\\   
    &\asymp d^{-4\alpha +2k_{0}}
    \end{split}
\end{equation}

\noindent\textbf{Term 2:} $\langle \Psi^{\frac{1}{2}}\beta, -(I-e^{-\Psi T})^{2}\overline{P}_0\Psi^{\frac{1}{2}}\beta\rangle$

We have 
\begin{equation}\begin{split}
    2) \coloneqq \langle \Psi^{\frac{1}{2}}\beta, -(I-e^{-\Psi T})^{2}\overline{P}_0\Psi^{\frac{1}{2}}\beta\rangle &\asymp \sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}} \frac{\sigma_{k}^{2}(1-e^{-\sigma_{k}^{2}T})^{2}}{\sigma_{k}^{2}\nu^{-1}+1}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}.
\end{split}
\end{equation}


\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}\label{eq:student2alpha1}
\begin{split}
    \langle \Psi^{\frac{1}{2}}\beta, -(I-e^{-\Psi T})^{2}\overline{P}_0\Psi^{\frac{1}{2}}\beta\rangle &\asymp -\frac{d^{-k_{0}-1}(1-d^{-\alpha})^{2}}{d^{-k_{0}-1+\alpha+1}+1}\sum_{l=1}^{N_{k_{0}}}\beta_{k_{0},l}^{2}\\
    &\asymp -(1-2d^{-\alpha}+d^{-2\alpha})
\end{split}
\end{equation}

\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\label{eq:student2alpha2}
\begin{split}
    \langle \Psi^{\frac{1}{2}}\beta, -(I-e^{-\Psi T})^{2}\overline{P}_0\Psi^{\frac{1}{2}}\beta\rangle &\asymp -\frac{d^{-k_{0}-1}(1-d^{-2\alpha+k_{0}})^{2}}{d^{\alpha-k_{0}}} \sum_{l=1}^{N_{k_{0}}}\beta_{k_{0},l}^{2}\\
    &\asymp -d^{-\alpha+k_{0}}(1-2d^{-2\alpha+k_{0}}+ d^{-4\alpha+2k_{0}})
\end{split}
\end{equation}

\noindent\textbf{Term 3:} $\langle \Psi^{\frac{1}{2}}\beta, \overline{P}_0(I-e^{-2\Psi T})\Psi^{\frac{1}{2}}\beta\rangle$

This term is treated similarly to the previous one
\begin{equation}
\begin{split}
    3) \coloneqq \langle \Psi^{\frac{1}{2}}\beta, \overline{P}_0(I-e^{-2\Psi T})\Psi^{\frac{1}{2}}\beta\rangle &\asymp \sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}} \frac{\sigma_{k}^{2}(1-e^{-2\sigma_{k}^{2}T})}{\sigma_{k}^{2}\nu^{-1}+1}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}
\end{split}
\end{equation}

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}\label{eq:student3alpha1}
\begin{split}
    \langle \Psi^{\frac{1}{2}}\beta, \overline{P}_0(I-e^{-2\Psi T})\Psi^{\frac{1}{2}}\beta\rangle &\asymp d^{-k_{0}-1}(1-d^{-2\alpha})\sum_{l=1}^{N_{k_{0}}}\beta_{k_{0},l}^{2}\\
    &\asymp (1-d^{-2\alpha})
\end{split}
\end{equation}

\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\label{eq:student3alpha2}
\begin{split}
    \langle \Psi^{\frac{1}{2}}\beta, \overline{P}_0(I-e^{-2\Psi T})\Psi^{\frac{1}{2}}\beta\rangle &\asymp d^{-\alpha+k_{0}}(1-d^{-4\alpha+2k_{0}}).
\end{split}
\end{equation}

Putting together the contributions of terms $2$ and $3$ we get in first order the following.

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}\label{eq:student23alpha1}
\begin{split}
    2)+3) &\asymp (2d^{-\alpha}-2d^{-2\alpha})\\
    &\lesssim d^{-\alpha}. 
\end{split}
\end{equation}

\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\label{eq:student23alpha2}
\begin{split}
    2)+3)&\asymp (2d^{-2\alpha+k_{0}}-2d^{-4\alpha+2k_{0}})d^{-\alpha+k_{0}}\\
    &\lesssim d^{-3\alpha+2k_{0}}.
\end{split}
\end{equation}
\noindent\textbf{Term 4:} $\langle \Psi^{\frac{1}{2}}\beta, \overline{\mathcal{P}}(S_T)\Psi^{\frac{1}{2}}\beta\rangle$

By Theorem \ref{theo:doubleresolventapprox} we have
\begin{equation}
    \langle \Psi^{\frac{1}{2}}\beta, \overline{\mathcal{P}}(S_T)\Psi^{\frac{1}{2}}\beta\rangle = \left\langle \Psi^{\frac{1}{2}}\beta, \frac{(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}+\frac{\frac{\Psi}{(I+\Psi \nu^{-1})^{2}}\operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)}}{d^{\alpha}-\operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi\nu^{-1})^{2}}\right)}} \Psi^{\frac{1}{2}}\beta\right\rangle
\end{equation}

Again, we treat each term separately. The first one is 
\begin{equation}
\begin{split}
4)(1) \coloneqq \left\langle \Psi^{\frac{1}{2}}\beta,
\frac{(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}
\Psi^{\frac{1}{2}}\beta\right\rangle
&=\sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}}\frac{d^{-k-1}(1-e^{-\sigma_{k}^{2}T})^{2}}{(1+d^{\alpha-k})^{2}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}.
\end{split}
\end{equation}

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}\label{eq:student4.1alpha1}
\begin{split}
\left\langle \Psi^{\frac{1}{2}}\beta,
\frac{(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}
\Psi^{\frac{1}{2}}\beta\right\rangle
&\asymp d^{-k_{0}-1}(1-d^{-\alpha})^{2}\sum_{l=1}^{N_{k_{0}}}\beta_{k,l}^{2}\\
&\asymp 1.
\end{split}
\end{equation}
\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\label{eq:student4.1alpha2}
\begin{split}
    \left\langle \Psi^{\frac{1}{2}}\beta,
\frac{(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}
\Psi^{\frac{1}{2}}\beta\right\rangle
&\asymp \frac{d^{-k_{0}-1}(1-d^{-2\alpha+k_{0}})^{2}}{d^{2\alpha-2k_{0}}}\sum_{l=1}^{N_{k_{0}}}\beta_{k,l}^{2}\\
&\asymp d^{-2\alpha +2k_{0}}
\end{split}
\end{equation}

For the second term,
\begin{equation}\label{eq:secondtermstudent}
\begin{split}
4)(2) \coloneqq \left\langle \Psi^{\frac{1}{2}}\beta,
\frac{\frac{\Psi}{(I+\Psi \nu^{-1})^{2}}\operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)}}{d^{\alpha}-\operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi\nu^{-1})^{2}}\right)}}\beta\right\rangle &= \sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}} \frac{\operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)}}{d^{\alpha}-\operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi \nu^{-1})^{2}}\right)}}\frac{\sigma_{k}^{4}N_{k}}{(1+d^{-k-1+2k_{0}+1})^{2}},
\end{split}
\end{equation}
we first observe that we can simplify the denominator. In fact, by \eqref{eq:nuequation}, we can write
\begin{equation}
    \begin{split}
        d^{\alpha} - \operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi \nu^{-1})^{2}}\right)} &= \operatorname{tr}{\left(\frac{\Psi\nu^{-1}}{I+\Psi \nu^{-1}}\right)} - \operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi \nu^{-1})^{2}}\right)}\\
        &= \operatorname{tr}{\left(\frac{\Psi\nu^{-1}+\Psi^{2}\nu^{-2}-\Psi^{2}\nu^{-2}}{(I+\Psi\nu^{-1})^{2}}\right)}\\
        &= \operatorname{tr}{\left(\frac{\Psi\nu^{-1}}{(I+\Psi\nu^{-1})^{2}}\right)}
    \end{split}
\end{equation}
such that we will need a lower bound for this trace.

\noindent\textbf{Lower bound for the denominator trace.}

We want to lower bound 
\begin{equation}
    \operatorname{tr}{\left(\frac{\Psi\nu^{-1}}{(I+\Psi\nu^{-1})^{2}}\right)} = \sum_{k\in \mathcal{K}} \frac{\sigma_{k}^{2}d^{\alpha+1}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}.
\end{equation}

Since the terms are positive, a single degree gives a lower bound. Let $k_{\alpha}$ be a fixed even degree with $k_{\alpha}>\alpha$, as in the proof of Lemma~\ref{lem:nu-relu}. Then $\sigma_{k_{\alpha}}^{2}d^{\alpha+1}\asymp d^{\alpha-k_{\alpha}}\to0$, so
\begin{equation}
    \operatorname{tr}{\left(\frac{\Psi\nu^{-1}}{(I+\Psi\nu^{-1})^{2}}\right)}\ \geq\ \frac{\sigma_{k_{\alpha}}^{2}d^{\alpha+1}}{(1+\sigma_{k_{\alpha}}^{2}d^{\alpha+1})^{2}}N_{k_{\alpha}}\ \asymp\ d^{-k_{\alpha}-1}d^{\alpha+1}d^{k_{\alpha}}=d^{\alpha}.
\end{equation}
Conversely, $\frac{\Psi\nu^{-1}}{(I+\Psi\nu^{-1})^{2}}\leq\frac{\Psi\nu^{-1}}{I+\Psi\nu^{-1}}$ and \eqref{eq:nuequation} give the upper bound $d^{\alpha}$. We conclude that
\begin{equation}
     \operatorname{tr}{\left(\frac{\Psi\nu^{-1}}{(I+\Psi\nu^{-1})^{2}}\right)} \asymp d^{\alpha}.
\end{equation}





















\noindent\textbf{Upper bound for the numerator trace.}

We want to calculate
\begin{equation}
    \operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)} = \sum_{k\in \mathcal{K}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}T})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}.
\end{equation}

Again, we divide into two cases depending on the value of $\alpha$.

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.} We use the stopping-time
\begin{equation}
    T = \frac{1}{\sigma_{k_{0}}^{2}}\log{(d^{\alpha})}
\end{equation}

let us divide the sum into four terms and calculate each one separately.

We divide the sum into four parts
\begin{equation}
    \begin{split}
        \operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)} &= 
        \underbrace{\sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq \alpha}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{\alpha})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(i)}\\
        &+\underbrace{\sum_{\substack{k\in \mathcal{K}\\ \alpha \leq k \leq k_{0}}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{\alpha})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(ii)}\\
        &+\underbrace{\sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq d}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{\alpha})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(iii)}\\
        &+ \underbrace{\sum_{\substack{k\in \mathcal{K}\\ k > d}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{\alpha})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(iv)}.
    \end{split}
\end{equation}

For the first sum, since $k\leq \alpha$ and $\alpha=O(1)$ then, in particular, $k\ll d$ and we can use $\sigma_{k}^{2} \asymp d^{-k-1}$ and $N_{k} \asymp d^{k}$ such that
\begin{equation}
\begin{split}
    (i) &\asymp \sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq \alpha}} \frac{d^{2\alpha+2}(1-e^{-d^{-k+k_{0}\log{(d^{\alpha})}}})^{2}}{(1+d^{-k-1}d^{\alpha+1})^{2}}d^{-k-1}d^{k}\\
    &\asymp d^{2\alpha+1}\sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq \alpha}} \frac{(1-e^{-d^{-k+k_{0}\log{(d^{\alpha})}}})^{2}}{(d^{\alpha-k})^{2}}
\end{split}
\end{equation}
where we used that $k<\alpha$ such that the denominator is dominated by the term $d^{\alpha-k}$. Moreover, since $k\leq \alpha \leq k_{0}$ then the exponential term is too small and we obtain
\begin{equation}
\begin{split}
    (i) &\asymp \sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq \alpha}}d^{2k+1} \lesssim d^{2\alpha+1}.
\end{split}
\end{equation}

Now, for the second term, since $k \leq k_{0}$ and $k_{0}=O(1)$ we can use again that $\sigma_{k}^{2}\asymp d^{-k-1}$ and $d^{k}$. Also, the exponential is still very small. However, the dominant term in the denominator is now $1$ and we get
\begin{equation}
   (ii) \asymp d^{2\alpha+2} \sum_{\substack{k\in \mathcal{K}\\ \alpha < k \leq k_{0}}} d^{-k-1}d^{k} \asymp d^{2\alpha+1}.
\end{equation}

For the third term the exponential is non-negligible and we use a Taylor expansion for it. Moreover, since $k\leq d$ and $d$ is large we have
\begin{equation}
\begin{split}
    \sigma_{k}^{2} &\asymp \frac{d^{d-1}}{(d+k)^{d+k}}\left(\frac{e}{2}\right)^{k}[(k-2)(k-3)...(k/2)]^{2}\\
    &\gtrsim \frac{d^{d-1}}{(2d)^{d+ k}} = d^{-k-1}2^{-d-k},
\end{split}
\end{equation}
such that
\begin{equation}\label{eq:generaldenominator}
    (1+\sigma_{k}^{2}d^{\alpha+1})^{2} \gtrsim (1+d^{\alpha-k}2^{-d-k}) \asymp 1.
\end{equation}
since we are in the case where $\alpha\leq k_{0} \leq k$.

Now, for $k\leq d$ we have
\begin{equation}
\begin{split}
    N_{k}\sigma_{k}^{2} &\asymp \frac{\sqrt{d}(2k+d)[(k-2)(k-3)...(k/2)]^{2}}{2^{k}k!(d+k)^{\frac{5}{2}}}\\
    &\lesssim \frac{d^{\frac{1}{2}+1}}{d^{\frac{5}{2}}}g(k) = \frac{1}{d}g(k)
\end{split}
\end{equation}
where
\begin{equation}
    g(k) \coloneqq \frac{[(k-2)(k-3)...(k/2)]^{2}}{2^{k}k!}
\end{equation}
and one can check that this function is decreasing in $k$.

Since in the range $2k_{0}+2 \leq k \leq d$ we cannot use $\sigma_{k}\asymp d^{-k-1}$ we prove the following result which will suffice for our purpose.

\begin{claim}\label{eq:lemmasigmadecreasing}
    We have that the sequence $(\sigma_{k})_{k \text{ even}}$ is decreasing. Moreover, for evert $k\in \mathbb{N}$ even we have
    \begin{equation}
        \frac{\sigma_{k+2}^{2}}{\sigma_{k}^{2}}  \lesssim \frac{1}{d^{2}}.
    \end{equation}
\end{claim}

\begin{proofclaim}
    Using \eqref{eq:sigmakasymptotics} we have
    \begin{equation}
    \begin{split}
        \frac{\sigma_{k+2}^{2}}{\sigma_{k}^{2}} &\asymp \frac{(d+k)^{d+k}}{(d+k+2)^{d+k+2}}\left(\frac{e}{2}\right)^{2}\left(\frac{k}{k/2}\right)^{2}\\
        &\asymp \frac{1}{(d+k+2)^{2}}\left(\frac{d+k}{d+k+1}\right)^{d+k}\\
    \end{split} 
    \end{equation}
Now, using that $\log{x}\leq x-1$ for $x=1 -\frac{1}{d+k+1}$ we obtain
\begin{equation}
    \left(\frac{d+k}{d+k+1}\right)^{d+k} \leq e^{-1}
\end{equation}
such that
\begin{equation}
    \begin{split}
        \frac{\sigma_{k+2}^{2}}{\sigma_{k}^{2}} &\lesssim \frac{1}{d^{2}}
    \end{split}
\end{equation}
as we wanted. \hfill \ensuremath{\blacksquare}
\end{proofclaim}
With the previous claim and calculations, we get
\begin{equation}
    (ii) \lesssim d^{2\alpha+2}\sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq d}} (d^{-k+k_{0}}\log{(d^{\alpha})})^2\frac{1}{d}g(k).
\end{equation}

Now, we need to subdivide into the cases where $k\ll d$ and $k=cd$ with $c \in(0,1]$. 

\noindent\underline{Subcase 1.1: $k\ll d$.} The function $g(k)$ does not contribute in leading order and we also note that the leading order is $k=k_{0}+2$ such that
\begin{equation}\label{eq:numerator(ii)1}
\begin{split}
    (ii) &\lesssim d^{2\alpha+2}d^{-4}(\log{(d^{\alpha})})^{2}d^{-1}\\
    &\asymp d^{2k_{0}-3}(\log{(d^{\alpha})})^{2}.
\end{split}   
\end{equation}

\noindent\underline{Subcase 1.2: $k=cd,\ c\in(0,1]$.} We can use a Stirling approximation for $g(k)$ and get
\begin{equation}
\begin{split}
    g(k) &=\frac{\left[\frac{(k-2)!}{(\frac{k}{2}-1)}\right]^{2}}{2^k k!} \asymp \frac{\left[k^{\frac{1}{2}}\left(\frac{k}{e}\right)^{k-2}k^{-\frac{1}{2}}\left(\frac{k}{2e}\right)^{-\frac{k}{2}+1}\right]^{2}}{2^{k}k^{\frac{1}{2}}\left(\frac{k}{e}\right)^{k}}\\
    &\asymp \frac{k^{2k-4}e^{-2k+4}k^{-k+2}2^{k-2}e^{k-2}}{2^{k}k^{\frac{1}{2}}k^{k}e^{-k}}\\
    &\asymp \frac{k^{k-2}e^{-k+2}2^{k-2}}{k^{k+\frac{1}{2}}e^{-k}2^{k}}\\
    &\asymp k^{-\frac{5}{2}}
 \end{split}
\end{equation}
such that
\begin{equation}\label{eq:}
    \begin{split}
        (iii) &\lesssim \sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq d\\ k=cd}} d^{2\alpha+2}[d^{-k+k_{0}}\log{(d^{\alpha})}]^{2} d^{-1}k^{-\frac{5}{2}}\\
        &\asymp d^{2\alpha+1}(\log{(d^{\alpha})})^{2}\sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq d\\ k=cd}} d^{-2cd+2k_{0}}(cd)^{-\frac{5}{2}}\\
        &\asymp d^{2\alpha + 2k_{0}-\frac{3}{2}}(\log{(d^{\alpha})})^{2}\sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq d\\ k=cd}}d^{-2cd}
    \end{split}
\end{equation}
which is superexponentially small in d. 

Finally, for the fourth term we can use the fact that $\sigma_{k}^{2}$ decreases in $k$ from Lemma \ref{eq:lemmasigmadecreasing} and \eqref{eq:generaldenominator} to conclude that the denominator is again lower bounded by something of order $1$. Using Lemma \eqref{eq:lemmasigmadecreasing} again in the exponential and Taylor expansion we obtain
\begin{equation}
    (iv) \lesssim \sum_{\substack{k\in \mathcal{K}\\ k > d}} d^{2\alpha+2}[d^{-k+k_{0}}\log{(d^{\alpha})}]^{2}N_{k}\sigma_{k}^{2}.
\end{equation}
Now, for $k>d$ we have $d$ and $k$ large such that
\begin{equation}
\begin{split}
    N_{k}\sigma_{k}^{2} &\asymp \frac{\sqrt{d}(2k+d)}{(d+k)^{\frac{5}{2}}}g(k)\\
    &\lesssim d^{\frac{1}{2}-\frac{5}{2}}kk^{-\frac{5}{2}}\\
    &\lesssim d^{-2}k^{-\frac{3}{2}} 
\end{split}
\end{equation}
where we used the fact that we already know $g(k)\asymp k^{-\frac{5}{2}}$ when $k$ is large. Then, we get
\begin{equation}
    (iv) \lesssim \sum_{\substack{k\in \mathcal{K}\\ k > d}}d^{2\alpha+2}d^{-2k+2k_{0}}(\log{(d^{\alpha})})^{2}d^{-2}k^{-\frac{3}{2}}
\end{equation}
we observe that the dominant term is for $k=d+1$ and that the series converges. We obtain
\begin{equation}
\begin{split}
    (iv) &\lesssim d^{2\alpha+2}\sum_{\substack{k\in \mathcal{K}\\ k > d}}d^{2k_{0}-2k}(\log{d^{\alpha}})^{2}d^{-2}k^{-\frac{3}{2}}\\
    &\asymp d^{2\alpha+2k_{0}-2d}(\log{(d^{\alpha})})^{2}(d+1)^{-\frac{3}{2}}
\end{split}
\end{equation}
where we used that the dominant term is for $k=d+1$.

\noindent\textbf{Case 2: $\alpha>k_{0}$.} We use the stopping-time
\begin{equation}
    T = \frac{1}{\sigma_{k_{0}}^{2}}\log{(d^{2\alpha-k_{0}})}
\end{equation}

We divide the sum into four terms again
\begin{equation}
    \begin{split}
        \operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)} &= 
        \underbrace{\sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq k_{0}}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{2\alpha-k_{0}})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(i)}\\
        &+\underbrace{\sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq \alpha}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{2\alpha-k_{0}})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(ii)}\\
        &+\underbrace{\sum_{\substack{k\in \mathcal{K}\\ \alpha+2 \leq k \leq d}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{2\alpha-k_{0}})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(iii)}\\
        &+ \underbrace{\sum_{\substack{k\in \mathcal{K}\\ k > d}}\frac{d^{2\alpha+2}(1-e^{-\sigma_{k}^{2}\sigma_{k_{0}}^{-2}\log{(d^{2\alpha-k_{0}})}})^{2}}{(1+\sigma_{k}^{2}d^{\alpha+1})^{2}}N_{k}\sigma_{k}^{2}}_{(iv)}.
    \end{split}
\end{equation}

For the first term, since $k\leq k_{0}$ we can use $\sigma_{k}^{2}\asymp d^{-k-1}$ and $N_{k} \asymp d^{k}$. Also, using that $k\leq k_{0} < \alpha$ we get
\begin{equation}\begin{split}
    (i) &\asymp \sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq k_{0}}}\frac{d^{2\alpha}(1-e^{-d^{-k+k_{0}}\log{(d^{2\alpha-k_{0}})}})^{2}}{(1+d^{-k-1}d^{\alpha+1})^{2}} d^{-k-1}d^{k}\\
    &\asymp \sum_{\substack{k\in \mathcal{K}\\ 0 \leq k \leq k_{0}}}\frac{d^{2\alpha+2}d^{-1}}{(d^{\alpha-k})^{2}}\\
    &\asymp d^{2k_{0}+1}.
\end{split}
\end{equation}

For the second term we need to use Taylor expansion in the exponential and we get
\begin{equation}
\begin{split}
    (ii) &\lesssim \sum_{\substack{k\in \mathcal{K}\\ k_{0}+1 \leq k \leq \alpha}} \frac{d^{2\alpha+1}(d^{-k+k_{0}}\log{(d^{2\alpha-k_{0}})})^{2}}{(d^{\alpha-k})^{2}}\\
    &\asymp d^{2\alpha+1}d^{2k_{0}-2\alpha}(\log{(d^{2\alpha-k_{0}})})^{2}\\
    &\asymp d^{2k_{0}+1}(\log{(d^{2\alpha-k_{0}})})^{2}.
\end{split}
\end{equation}

For the third term, we have the same reasoning as previous $(iii)$ but now the logarithm term changed and also the dominant term is $k=\alpha+1$. 

\noindent\underline{Subcase 2.1: $k\ll d$.} We get
\begin{equation}\begin{split}
    (iii) &\lesssim d^{2\alpha+2}(d^{k_{0}-\alpha-1}\log{(d^{2\alpha-k_{0}})})^{2}d^{-1}\\
    &\lesssim d^{2k_{0}-1}(\log{(d^{2\alpha-k_{0}})})^{2}
\end{split}
\end{equation}
\noindent\underline{Subcase 2.2: $k=cd,\ c\in(0,1]$.} We get
\begin{equation}
    (iii) \lesssim d^{2\alpha + 2k_{0}-\frac{3}{2}}(\log{(d^{2\alpha-k_{0}})})^{2}\sum_{\substack{k\in \mathcal{K}\\ k_{0}+2 \leq k \leq d\\ k=cd}}d^{-2cd}.
\end{equation}

The fourth term is also the same as before just changing the logarithm term, we get
\begin{equation}
    (iv) \lesssim d^{2\alpha+2k_{0}-2d}(\log{(d^{\alpha})})^{2}. 
\end{equation}


\noindent\textbf{Combining the trace bounds.}

\noindent\textbf{Case 1: $0<\alpha\leq k_{0}$.}
\begin{equation}\label{eq:student4.2alpha1}
\begin{split}
4)(2) = \left\langle \Psi^{\frac{1}{2}}\beta,
\frac{\frac{\Psi}{(I+\Psi \nu^{-1})^{2}}\operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)}}{d^{\alpha}-\operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi\nu^{-1})^{2}}\right)}}\Psi^{\frac{1}{2}}\beta\right\rangle &= \sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}}\frac{d^{2\alpha+1}}{d^{\alpha}}\frac{\sigma_{k}^{4}}{(1+d^{-k+1+\alpha+1})^{2}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}\\
&\asymp d^{\alpha+1}d^{-k_{0}-1}\\
&\asymp d^{\alpha-k_{0}}.
\end{split}
\end{equation}
\noindent\textbf{Case 2: $\alpha>k_{0}$.}
\begin{equation}\label{eq:student4.2alpha2}
\begin{split}
4)(2) = \left\langle \Psi^{\frac{1}{2}}\beta,
\frac{\frac{\Psi}{(I+\Psi \nu^{-1})^{2}}\operatorname{tr}{\left(\frac{\nu^{-2}\Psi(I-e^{-\Psi T})^{2}}{(I+\Psi\nu^{-1})^{2}}\right)}}{d^{\alpha}-\operatorname{tr}{\left(\frac{\Psi^{2}\nu^{-2}}{(I+\Psi\nu^{-1})^{2}}\right)}}\Psi^{\frac{1}{2}}\beta\right\rangle &= \sum_{\substack{k\in \mathcal{K}\\ 1 \leq k \leq k_{0}}}\frac{d^{2k_{0}+1}}{d^{\alpha}}\frac{\sigma_{k}^{4}}{(1+d^{-k+1+\alpha+1})^{2}}\sum_{l=1}^{N_{k}}\beta_{k,l}^{2}\\
&\asymp \frac{d^{2k_{0}+1}}{d^{\alpha}}\frac{d^{-k_{0}-1}}{d^{2\alpha-2k_{0}}}\\
&\asymp d^{-3\alpha+3k_{0}}.
\end{split}
\end{equation}

Finally, comparing the terms \eqref{eq:student1alpha1},\eqref{eq:student23alpha1}, \eqref{eq:student4.1alpha1}, \eqref{eq:student4.2alpha1} and \eqref{eq:student1alpha2},\eqref{eq:student23alpha2}, \eqref{eq:student4.1alpha2}, \eqref{eq:student4.2alpha2} we obtain
\begin{equation}
    \overline{\mathcal{L}}_{\mathrm{ST}}(T) \asymp \begin{cases}
        1,\; \text{ if $\alpha \in (0,\;k_{0}]$},\;\\
        d^{-2\alpha+2k_{0}},\; \text{ if $\alpha > k_{0}$}.\\
    \end{cases}
\end{equation}

Comparing with \eqref{eq:teacherreluerror}, under the unit norm hypothesis, we obtain
\begin{equation}
    \overline{\mathcal{L}}_{\mathrm{ST}}(T) \asymp \overline{\mathcal{L}}_{\mathrm{TE}}^{2}
\end{equation}
as we wanted.

