\label{lem:mixed-nu-consequences}
Fix $\alpha>1$ and $m=d^\alpha$, and let $k\in\mathcal K$ be a fixed degree. With constants depending only on $\alpha$ and $k$,
\begin{equation*}
\begin{aligned}
&\text{(i)}\quad \frac{\nu}{\sigma_k^2+\nu}\asymp d^{k-\alpha}\quad(k<\alpha),
&\qquad&\text{(ii)}\quad \frac{\nu}{\sigma_k^2+\nu}\longrightarrow1\quad(k>\alpha),\\[4pt]
&\text{(iii)}\quad \operatorname{tr}\Psi\asymp d^{-1},
&\qquad&\text{(iv)}\quad \nu\operatorname{tr}[\Psi(\Psi+\nu I)^{-2}]\asymp m.
\end{aligned}
\end{equation*}

\label{lem:mixed-filter}
Fix $\alpha>1$, $m=d^\alpha$, and a harmonic degree $j\in\mathcal K$ with $j<\alpha$. There is a constant $C_{\alpha,j}$ such that for all $x\ge0$ and all large $d$,
\begin{equation}\label{eq:mixed-filter}
\overline H(x/\sigma_j^2)\le C_{\alpha,j}\,(1+x^2)\,d^{2j-2\alpha}.
\end{equation}

